using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace ContourWatch {
 public sealed class AgentSaveDialog:Form {
  readonly TextBox folder=new TextBox(),name=new TextBox();readonly ListBox directories=new ListBox();readonly Label status=new Label();readonly string suffix;string current;
  public string FileName{get;private set;}
  public AgentSaveDialog(string extension){suffix=extension;Text="Контур · сохранить диагностику";Width=720;Height=530;MinimumSize=new Size(560,400);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;Padding=new Padding(12);
   var top=new TableLayoutPanel{Dock=DockStyle.Top,Height=72,ColumnCount=3,RowCount=2};top.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));top.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,90));top.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,100));top.Controls.Add(new Label{Text="Папка сохранения",AutoSize=true},0,0);top.SetColumnSpan(top.GetControlFromPosition(0,0),3);folder.Dock=DockStyle.Fill;top.Controls.Add(folder,0,1);var go=new Button{Text="Перейти",Dock=DockStyle.Fill};go.Click+=(s,e)=>Navigate(folder.Text);top.Controls.Add(go,1,1);var up=new Button{Text="Вверх ↑",Dock=DockStyle.Fill};up.Click+=(s,e)=>{try{var parent=Directory.GetParent(current??folder.Text);if(parent!=null)Navigate(parent.FullName);else Drives();}catch(Exception ex){status.Text=ex.Message;}};top.Controls.Add(up,2,1);
   directories.Dock=DockStyle.Fill;directories.HorizontalScrollbar=true;directories.DoubleClick+=(s,e)=>OpenSelected();directories.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;OpenSelected();}};folder.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;Navigate(folder.Text);}};
   var bottom=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=135,ColumnCount=2,RowCount=3};bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));bottom.Controls.Add(new Label{Text="Имя файла ("+suffix+")",AutoSize=true},0,0);name.Dock=DockStyle.Fill;name.Text="ContourWatch-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+suffix;bottom.Controls.Add(name,0,1);var save=new Button{Text="Сохранить",Dock=DockStyle.Fill};save.Click+=(s,e)=>Save();bottom.Controls.Add(save,1,1);status.Dock=DockStyle.Fill;status.AutoEllipsis=true;bottom.Controls.Add(status,0,2);var cancel=new Button{Text="Отмена",Dock=DockStyle.Fill,DialogResult=DialogResult.Cancel};bottom.Controls.Add(cancel,1,2);CancelButton=cancel;AcceptButton=save;Controls.Add(directories);Controls.Add(bottom);Controls.Add(top);AgentTheme.Apply(this);
   string initial=Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);if(!Directory.Exists(initial))initial=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);Navigate(initial);
  }
  void Navigate(string path){try{string resolved=Path.GetFullPath(path);var list=Directory.EnumerateDirectories(resolved).Where(p=>(File.GetAttributes(p)&FileAttributes.Hidden)==0).OrderBy(p=>p,StringComparer.CurrentCultureIgnoreCase).Take(500).ToArray();directories.Items.Clear();foreach(string p in list)directories.Items.Add(new Entry(p));current=resolved;folder.Text=resolved;status.Text="Выберите подпапку двойным щелчком или укажите путь сверху.";}catch(Exception e){status.Text="Папка недоступна: "+e.Message;}}
  void Drives(){current=null;directories.Items.Clear();foreach(string drive in Directory.GetLogicalDrives())directories.Items.Add(new Entry(drive));status.Text="Выберите диск.";}
  void OpenSelected(){var entry=directories.SelectedItem as Entry;if(entry!=null)Navigate(entry.Path);}
  void Save(){try{string directory=Path.GetFullPath(folder.Text);if(!Directory.Exists(directory))throw new IOException("Указанная папка не существует");string file=name.Text.Trim();if(String.IsNullOrEmpty(file)||file.IndexOfAny(Path.GetInvalidFileNameChars())>=0||file=="."||file=="..")throw new IOException("Укажите корректное имя файла без пути");if(!file.EndsWith(suffix,StringComparison.OrdinalIgnoreCase))file+=suffix;string target=Path.Combine(directory,file);if(File.Exists(target)&&AgentTheme.ShowMessage(this,"Заменить существующий файл?\r\n"+target,"Контур · подтверждение",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return;FileName=target;DialogResult=DialogResult.OK;Close();}catch(Exception e){status.Text=e.Message;}}
  class Entry{public readonly string Path;public Entry(string p){Path=p;}public override string ToString(){return Directory.GetParent(Path)==null?Path:System.IO.Path.GetFileName(Path);}}
 }
}
